using TownOfHost;
using TownOfHost.Roles.Core;
using AmongUs.GameOptions;
class Program {
 static int passed;
 static readonly CustomRoles[] HamoTargets={CustomRoles.Catalyst,CustomRoles.Conductor,CustomRoles.Trauma,CustomRoles.Surmount,CustomRoles.MemoryRestorer,CustomRoles.Sender,CustomRoles.Fugitive,CustomRoles.Messenger,CustomRoles.ArchVillain,CustomRoles.LonelyWolf,CustomRoles.Clockworker,CustomRoles.Abductor,CustomRoles.MadInvisible,CustomRoles.MadMagic,CustomRoles.MadSender,CustomRoles.Parity,CustomRoles.Lupin,CustomRoles.Daoshi,CustomRoles.Flatfish,CustomRoles.Surviving,CustomRoles.Berserker,CustomRoles.ToughGuy,CustomRoles.Comorbidity,CustomRoles.Murder,CustomRoles.BetrayGuesser,CustomRoles.Experiencer};
 static readonly CustomRoles[] TempTargets={CustomRoles.StepBomber,CustomRoles.Locksmith,CustomRoles.Coroner};
 static readonly CustomRoles[] Targets=HamoTargets.Concat(TempTargets).ToArray();
 static From Expected(CustomRoles r)=>TempTargets.Contains(r)?From.TownOfHost_Temp:From.TownOfHost_hamo;
 static string ExpectedName(CustomRoles r)=>TempTargets.Contains(r)?ShellRoleOrigins.TempDisplayName:ShellRoleOrigins.HamoDisplayName;
 static readonly CustomRoles[] ShellRoles={CustomRoles.Tuner,CustomRoles.MadCleaner,CustomRoles.Chief,CustomRoles.Streamer,CustomRoles.Prankster,CustomRoles.Lethe,CustomRoles.Tiger};
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Test(string name,Action test){Options.Reset();test();passed++;Console.WriteLine("PASS "+name);}
 static SimpleRoleInfo Create(CustomRoles r,From f=From.None,int id=800000)=>SimpleRoleInfo.Create(typeof(RoleBase),p=>new RoleBase(),r,()=>RoleTypes.Crewmate,CustomRoleTypes.Crewmate,id,null,"test",from:f);
 static void Main(){
 Test("exactly the requested 29 role overrides",()=>{Check(Targets.Length==29&&Targets.Distinct().Count()==29,"target list");foreach(var r in Enum.GetValues<CustomRoles>())Check(ShellRoleOrigins.HasOverride(r)==Targets.Contains(r),"scope "+r);});
 Test("all 29 override conflicting upstream values",()=>{foreach(var r in Targets)foreach(var f in Enum.GetValues<From>())Check(ShellRoleOrigins.Resolve(r,f)==Expected(r),"override "+r);});
 Test("all other roles retain upstream metadata",()=>{foreach(var r in Enum.GetValues<CustomRoles>().Except(Targets))foreach(var f in Enum.GetValues<From>())Check(ShellRoleOrigins.Resolve(r,f)==f,"unexpected attribution "+r);});
 Test("26 hamo and 3 Temp format exact source names in both themes",()=>{foreach(var r in Targets)foreach(var f in Enum.GetValues<From>())foreach(var dark in new[]{true,false})Check(UtilsOption.GetFrom(f,r,dark).RemoveHtmlTags()=="From:"+ExpectedName(r),"render "+r);});
 Test("untargeted renderer output matches baseline exhaustively",()=>{foreach(var r in Enum.GetValues<CustomRoles>().Except(Targets))foreach(var f in Enum.GetValues<From>().Where(f=>f!=From.TownOfHost_Temp))foreach(var dark in new[]{true,false})Check(UtilsOption.GetFrom(f,r,dark)==BaselineUtilsOption.GetFrom(f,r,dark),"changed render "+r);});
 Test("actual SimpleRoleInfo registration applies overrides before consumers",()=>{foreach(var r in Targets.Take(19)){Options.Reset();var i=Create(r,From.SuperNewRoles);Check(i.From==From.TownOfHost_hamo&&CustomRoleManager.AllRolesInfo[r]==i,"registration "+r);Check(UtilsOption.GetFrom(i).RemoveHtmlTags()=="From:TownOfHost-hamo","info overload");Check(i.ConfigId==800000&&i.ChatCommand=="test"&&i.OptionSort==(0,0)&&i.Combination==CombinationRoles.None,"metadata changed");}});
 Test("Shell original attribution and special Tiger text remain",()=>{foreach(var r in ShellRoles){Options.Reset();var i=Create(r,From.TownOfHost_Shell);Check(i.From==From.TownOfHost_Shell,"Shell metadata "+r);Check(UtilsOption.GetFrom(i)==BaselineUtilsOption.GetFrom(From.TownOfHost_Shell,r),"Shell render");}});
 Test("actual role option setup overrides only From",()=>{foreach(var r in Targets){Options.Reset();var o=Options.SetupRoleOptions(800000,TabGroup.Addons,r,fromtext:"UPSTREAM");Check(o.Fromtext.Contains(ExpectedName(r))&&!o.Fromtext.Contains("UPSTREAM"),"option origin "+r);Check(o.Id==800000&&o.Name==r.ToString()&&o.Value==0&&Options.CustomRoleCounts[r].Id==800001,"option metadata changed");}});
 Test("actual info-based option setup shares attribution",()=>{foreach(var r in Targets.Take(19)){Options.Reset();var i=Create(r);Options.SetupRoleOptions(i);Check(Options.CustomRoleSpawnChances[r].Fromtext.Contains("TownOfHost-hamo"),"info option "+r);}});
 Test("untargeted options retain explicitly supplied From text",()=>{foreach(var r in new[]{CustomRoles.Prankster,CustomRoles.Lethe,CustomRoles.Arsene,CustomRoles.Kyonshi,CustomRoles.Conjurer,CustomRoles.Rocket}){Options.Reset();var o=Options.SetupRoleOptions(800000,TabGroup.Addons,r,fromtext:"KEEP EXACT");Check(o.Fromtext.Contains("KEEP EXACT")&&!o.Fromtext.Contains("TownOfHost-hamo"),"untargeted option "+r);}});
 Test("all six addon descriptions include shared From",()=>{foreach(var r in Targets.Skip(19).Take(6)){Check(UtilsShowOption.AddonInfo(r).Contains("TownOfHost-hamo"),"addon direct "+r);var help=UtilsShowOption.GetAddonsHelp(r);Check(help.Contains("TownOfHost-hamo"),"addon fallback "+r);Check(help.Contains(r+"--100...?(´・ω・｀)"),"pre-existing fallback text changed");}});
 Test("untargeted addon formatter output matches baseline exhaustively",()=>{foreach(var r in Enum.GetValues<CustomRoles>().Except(Targets))foreach(var f in Enum.GetValues<From>().Where(f=>f!=From.TownOfHost_Temp))Check(UtilsShowOption.AddonInfo(r,from:f)==BaselineUtilsShowOption.AddonInfo(r,from:f),"addon changed "+r);});
 Test("untargeted addon help output matches baseline",()=>{foreach(var r in Enum.GetValues<CustomRoles>().Except(Targets).Except(new[]{CustomRoles.Inheritance}))Check(UtilsShowOption.GetAddonsHelp(r)==BaselineUtilsShowOption.GetAddonsHelp(r),"help changed "+r);});
 Test("From changes do not change settings groups",()=>{foreach(var r in Targets.Take(19)){Options.Reset();var i=Create(r);var o=new OptionItem{CustomRole=r};var after=SettingsGroups.Group(o);i.From=From.None;Check(after==SettingsGroups.Group(o),"group changed "+r);}});
 Test("Temp registration and option text share one source",()=>{foreach(var r in TempTargets){Options.Reset();var i=Create(r,From.SuperNewRoles);Check(i.From==From.TownOfHost_Temp,"Temp registration");Options.SetupRoleOptions(i);Check(UtilsOption.GetFrom(i).RemoveHtmlTags()=="From:TownOfHost_Temp"&&Options.CustomRoleSpawnChances[r].Fromtext.Contains("TownOfHost_Temp"),"Temp label");Check(i.ConfigId==800000&&i.ChatCommand=="test"&&i.OptionSort==(0,0),"metadata changed");}});
 Test("Temp uses official color and hamo retains its color in both themes",()=>{foreach(var dark in new[]{true,false}){var h=UtilsOption.GetFrom(From.TownOfHost_hamo,CustomRoles.Experiencer,dark);Check(h.Contains("<#fb85ff>TownOfHost-hamo</color>"),"hamo color changed");foreach(var r in TempTargets){var text=UtilsOption.GetFrom(From.None,r,dark);Check(text==h.Replace("TownOfHost-hamo","TownOfHost_Temp").Replace("#fb85ff","#ffeb99"),"Temp color or label differs");Check(!text.Contains("FFD700",StringComparison.OrdinalIgnoreCase),"unexpected gold");}}});
 Test("existing From enum numeric values remain stable",()=>{var old=new[]{From.None,From.AmongUs,From.TheOtherRoles,From.TOR_GM_Edition,From.TOR_GM_Haoming_Edition,From.SuperNewRoles,From.ExtremeRoles,From.NebulaontheShip,From.au_libhalt_net,From.FoolersMod,From.SheriffMod,From.Jester,From.TownOfUs,From.TownOfHost,From.TownOfHost_Y,From.TownOfHost_K,From.TownOfHost_for_E,From.TownOfHost_Enhanced,From.TownOfHost_Pko,From.Speyrp,From.RevolutionaryHostRoles,From.Love_Couple_Mod,From.TownOfHost_hamo,From.TownOfHost_Shell};for(int n=0;n<old.Length;n++)Check((int)old[n]==n,"enum changed");Check((int)From.TownOfHost_Temp==old.Length,"Temp not appended");});
 Test("hamo override membership remains exactly 26 roles",()=>Check(HamoTargets.Length==26&&TempTargets.Length==3,"override count"));
 Test("typed Temp and all three overrides share official color for every upstream source",()=>{foreach(var dark in new[]{true,false}){var expected=UtilsOption.GetFrom(From.TownOfHost_Temp,CustomRoles.NotAssigned,dark);Check(expected==$"<#{(dark ? "000000" : "ffffff")}>From:</color><#ffeb99>TownOfHost_Temp</color>","literal Temp");foreach(var r in TempTargets)foreach(var f in Enum.GetValues<From>())Check(UtilsOption.GetFrom(f,r,dark)==expected,"Temp override "+r);}});
 Console.WriteLine($"RESULT {passed} passed, 0 failed");
 }
}
